//! Vectors for `fold_output` (`blocks/iop/fold.h`), generated by
//! `scripts/cpp_vectors/fold_output_vectors.cpp`.

use std::collections::HashMap;

use fp_core::code::code::Code;
use fp_core::field::ext::{F, E};
use fp_core::iop::fold::{fold_output, FoldShape};
use fp_core::iop::relation::{Codes, GroupLayout, GroupRow, Part, Statement};
use fp_core::iop::tensor::Tensor;

const VECTORS: &str = include_str!("../../fixtures/fold_output_vectors.txt");

fn fields(line: &str) -> HashMap<&str, &str> {
    line.split_whitespace()
        .filter_map(|t| t.split_once('='))
        .map(|(k, v)| (k, v))
        .collect()
}
fn e(s: &str) -> E {
    let p: Vec<&str> = s.split(',').collect();
    E([
        F(u64::from_str_radix(p[0], 16).unwrap()),
        F(u64::from_str_radix(p[1], 16).unwrap()),
        F(u64::from_str_radix(p[2], 16).unwrap()),
    ])
}
fn mk(x: u64) -> E {
    E([F(x), F(x + 1), F(x + 2)])
}
fn elist(s: &str) -> Vec<E> {
    if s == "-" {
        return Vec::new();
    }
    s.split(';').map(e).collect()
}
fn hex(v: &[E]) -> String {
    v.iter()
        .map(|x| format!("{:016x},{:016x},{:016x}", x.0[0].0, x.0[1].0, x.0[2].0))
        .collect::<Vec<_>>()
        .join(";")
}

#[test]
fn fold_output_vectors_match_the_cpp_reference() {
    let mut seen = 0usize;
    for line in VECTORS.lines() {
        let first = line.split_whitespace().next().unwrap();
        let kv = fields(line);
        match first {
            "FOLD_OUTPUT" => {
                let out = run();
                assert_eq!(out.masks.to_string(), kv["masks"]);
                assert_eq!(out.d.len().to_string(), kv["d"]);
                assert_eq!(out.kept.len().to_string(), kv["kept"]);
                assert_eq!(out.gamma.len().to_string(), kv["gamma"]);
                assert_eq!(format!("{:016x},{:016x},{:016x}", out.target.0[0].0, out.target.0[1].0, out.target.0[2].0), kv["target"]);
                seen += 1;
            }
            "FOLD_C" => {
                let out = run();
                let c: Vec<E> = (0..4).map(|j| out.c.at(j)).collect();
                assert_eq!(hex(&c), kv["FOLD_C"]);
            }
            "FOLD_D0" => assert_eq!(hex(&run().d[0]), kv["FOLD_D0"]),
            "FOLD_D1" => assert_eq!(hex(&run().d[1]), kv["FOLD_D1"]),
            _ => {}
        }
    }
    assert!(seen > 0);
}

fn run() -> fp_core::iop::single_rows::SingleRows {
    let codes = Codes {
        base: vec![Code { log_n: 3, ell: 4, r: 2 }],
        mask: vec![Code { log_n: 2, ell: 4, r: 2 }],
    };
    let st = Statement::new(codes);
    let layout = GroupLayout { k: 1, h: 1, log_ell: 2, log_ell_zk: 2, ..GroupLayout::default() };
    let f = [F(2), F(3), F(4)];
    let mut row = GroupRow::default();
    row.c.add(Tensor::product(&f, 3, mk(5)));
    row.d = (0..8).map(|i| mk(300 + i)).collect();
    row.target = mk(301);
    let shape = FoldShape { code: 0, mask_code: 0, layout, ..FoldShape::default() };
    fold_output(&st, &shape, row, 1, mk(76), &[mk(80)], mk(81))
}
